(() => {
  'use strict';
  const sample=window.RAJE3_SAMPLE;
  const labels=sample.statusLabels;
  const steps=['بدء مراجعة','فحص النطاق','تقرير النتائج'];
  const number=new Intl.NumberFormat('ar-SA-u-ca-gregory',{numberingSystem:'arab'});
  const date=new Intl.DateTimeFormat('ar-SA-u-ca-gregory',{day:'numeric',month:'long',year:'numeric',numberingSystem:'arab'});
  const state={step:0,reached:0,name:sample.review.name,requirements:sample.review.inputRequirements.join('\n'),files:sample.review.selectedFiles.map(name=>({name,demo:true})),busy:false,runStage:0,selected:'r4',preview:'r4',focus:false,filter:'attention',file:null,tab:'requirements',error:'',customBlocked:false};
  const app=document.getElementById('app');
  const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const n=v=>number.format(v);
  const paths={
    logo:'M4 5H1v14h3M20 5h3v14h-3M8 12l3 3 6-7',
    file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6',
    files:'M16 2H6a2 2 0 0 0-2 2v14M8 6h8l4 4v10a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2M16 6v4h4',
    close:'M6 6l12 12M6 18 18 6',
    check:'M20 6 9 17l-5-5',
    warning:'m12 3 10 18H2zM12 9v4M12 17h.01',
    unknown:'M9 9a3 3 0 0 1 6 0c0 2-3 2-3 5M12 18h.01',
    info:'M12 11v6M12 7h.01',
    lock:'M6 11h12v10H6zM8 11V7a4 4 0 0 1 8 0v4',
    code:'m8 5-6 7 6 7M16 5l6 7-6 7M14 4l-4 16',
    target:'M12 2a10 10 0 1 0 10 10M12 7a5 5 0 1 0 5 5M12 12l9-9M16 3h5v5',
    list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',
    plus:'M12 5v14M5 12h14',
    clock:'M12 8v5l3 2',
    keyboard:'M3 5h18v14H3zM6 9h.01M10 9h.01M14 9h.01M18 9h.01M6 12h.01M10 12h.01M14 12h.01M18 12h.01M7 16h10',
    focus:'M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5'
  };
  function icon(name){const circle=['unknown','info','clock'].includes(name)?'<circle cx="12" cy="12" r="10"/>':'';return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${circle}<path d="${paths[name]||paths.file}"/></svg>`;}
  const statusClass=s=>s==='needs_review'?'warning':s==='appears_met'?'success':'unknown';
  const statusIcon=s=>s==='needs_review'?'warning':s==='appears_met'?'check':'unknown';
  const statusPill=s=>`<span class="pill ${statusClass(s)}">${icon(statusIcon(s))}${labels[s]}</span>`;
  const reqLines=()=>state.requirements.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);
  const ready=()=>state.files.length>0&&reqLines().length>0;
  const demo=()=>state.files.length===3&&state.files.every(f=>f.demo)&&state.files.map(f=>f.name).sort().join('|')===sample.review.selectedFiles.slice().sort().join('|')&&JSON.stringify(reqLines())===JSON.stringify(sample.review.inputRequirements);
  function announce(text){document.getElementById('announcer').textContent=text;}
  function stage(next){if(state.busy)return;state.step=next;state.reached=Math.max(next,state.reached);state.error='';if(next!==2)state.focus=false;render({view:true});document.getElementById('page-heading')?.focus();window.scrollTo({top:0,behavior:'instant'});announce(steps[next]);}
  function header(){return `<header class="shell"><div class="masthead"><button class="brand" data-action="home" aria-label="راجع، بدء المراجعة"><span class="brand-symbol">${icon('logo')}</span><span class="brand-word">راجع</span><span class="brand-description">مختبر الكود</span></button><nav aria-label="مراحل المراجعة"><ol class="steps">${steps.map((s,i)=>`<li><button class="step ${i===state.step?'current':i<state.step?'done':''}" data-action="stage" data-value="${i}" ${i>state.reached||state.busy?'disabled':''} ${i===state.step?'aria-current="step"':''}><span class="step-number">${n(i+1)}</span>${s}</button></li>`).join('')}</ol></nav><div class="top-actions"><button class="quiet" data-action="example" ${state.busy?'disabled':''}>تجربة المثال</button><button class="icon-button shortcut-trigger" data-action="shortcuts" aria-label="اختصارات لوحة المفاتيح" title="اختصارات لوحة المفاتيح" ${state.busy?'disabled':''}>${icon('keyboard')}</button><span class="demo-pill">${icon('code')}معاينة تفاعلية</span></div><div class="mobile-step"><strong>${n(state.step+1)} من ${n(3)}</strong>، ${steps[state.step]}</div></div></header>`;}
  function footer(){return `<footer class="shell"><div class="site-footer"><span class="footer-brand">${icon('logo')}راجع، قبل أن تعتبر المهمة مكتملة.</span><span>تصميم مختبر الكود، ببيانات توضيحية.</span><button class="link-button" data-action="about">عن هذه المعاينة</button></div></footer><dialog id="about-dialog" aria-labelledby="about-heading"><div class="dialog-head"><h2 id="about-heading">جرّب التصميم، وافهم الرحلة</h2><button class="icon-button" data-action="close-dialog" aria-label="إغلاق">${icon('close')}</button></div><p>هذه معاينة تفاعلية لتصميم راجع. التقرير يخص مثال تسجيل الدخول الجاهز، ولا يمثل تحليلًا فعليًا لملفات تختارها.</p><p>اختيار ملفات من جهازك يعرض أسماءها فقط داخل المعاينة؛ لا تُقرأ محتوياتها ولا تُرفع إلى خادم. لا يُشغّل الكود أو الاختبارات.</p><button class="primary" data-action="close-dialog">فهمت</button></dialog>`;}
  function syntax(text){const re=/("(?:\\.|[^"\\])*"|\b(?:return|if|function|false)\b)/g;let out='',at=0;for(const m of text.matchAll(re)){out+=esc(text.slice(at,m.index));out+=`<span class="${m[0].startsWith('"')?'syntax-string':'syntax-keyword'}">${esc(m[0])}</span>`;at=m.index+m[0].length;}return out+esc(text.slice(at));}
  function codeWindow(evidence,context=false){let snippet=evidence.snippet,start=evidence.lineStart;if(context&&evidence.file==='validators.js'&&evidence.lineStart===14){snippet=sample.review.results[0].evidence.snippet;start=12;}return `<div class="code-window"><div class="code-title"><span class="inline-note">${icon('file')}<bdi dir="ltr">${esc(evidence.file)}</bdi></span><span>السطر ${n(evidence.lineStart)}</span></div><div class="code-body" tabindex="0" aria-label="مقتطف كود للقراءة فقط من ${esc(evidence.file)}"><div role="code">${snippet.split('\n').map((line,i)=>`<div class="code-line ${start+i>=evidence.lineStart&&start+i<=evidence.lineEnd?'highlight':''}"><span class="line-number" aria-hidden="true">${start+i}</span><code>${syntax(line)}</code></div>`).join('')}</div></div></div>`;}
  function fileItems(removable){return state.files.map((file,i)=>`<li class="file-item">${icon('file')}<bdi dir="ltr">${esc(file.name)}</bdi>${file.demo?'<span class="file-kind">مثال</span>':''}${removable?`<button class="icon-button" data-action="remove-file" data-value="${i}" aria-label="إزالة ${esc(file.name)}">${icon('close')}</button>`:''}</li>`).join('');}
  function blockedNotice(){return `<div class="notice ${state.customBlocked?'':'hidden'}" id="custom-notice">${icon('info')}<div><strong>التقرير التوضيحي مرتبط بالمثال الجاهز</strong><p>يمكنك تجربة إدخال بياناتك وفحص نطاقها. التحليل الفعلي غير مفعّل في هذه المعاينة.</p><button class="link-button" data-action="example">استعادة المثال وتجربة التقرير</button></div></div>`;}
  function setup(){return `<div class="intro"><div><span class="eyebrow">${icon('code')}قبل أن تقول: خلصت.</span><h1 id="page-heading" tabindex="-1">راجع كودك، وافهم ما ينقصه.</h1><p>حدّد الملفات وأضف المتطلبات، ثم اطّلع على الملاحظات وأدلتها في تقرير واضح.</p></div><span class="inline-note">${icon('lock')}قراءة فقط، ضمن اختيارك.</span></div><div class="start-layout"><section class="panel form-panel" aria-label="بدء مراجعة"><div class="field"><label class="label" for="review-name">اسم المراجعة <span class="optional">اختياري</span></label><input id="review-name" type="text" dir="auto" placeholder="مثال: مراجعة تسجيل الدخول" value="${esc(state.name)}" autocomplete="off"></div><div class="file-section" id="drop-zone"><div class="file-zone-head"><h2 class="file-zone-title">${icon('files')}ملفات المراجعة <span class="caption" id="file-count">${state.files.length?n(state.files.length):'لا توجد ملفات'}</span></h2><button class="secondary" data-action="pick-files">اختيار الملفات</button><input type="file" id="file-input" multiple hidden></div><ul class="file-list">${state.files.length?fileItems(true):'<li class="empty-list">اختر الملفات التي تريد مراجعتها، أو اسحبها هنا.</li>'}</ul><p class="file-help">${state.files.every(f=>f.demo)&&state.files.length?'ملفات المثال الجاهز للتجربة. يمكنك إزالتها أو اختيار ملفاتك.':'اختيار ملفاتك يعرض أسماءها فقط في هذه المعاينة.'}</p></div><div class="field"><label class="label" for="requirements">المتطلبات <span class="caption" id="requirements-count">${n(reqLines().length)} متطلبات</span></label><textarea id="requirements" dir="auto" aria-describedby="requirements-hint" placeholder="اكتب كل متطلب في سطر مستقل">${esc(state.requirements)}</textarea><p id="requirements-hint" class="caption">اكتب كل متطلب في سطر مستقل، واذكر السلوك المتوقع بوضوح.</p></div>${blockedNotice()}<p class="validation" id="validation" role="status">${!ready()?'اختر ملفًا واحدًا على الأقل وأضف المتطلبات للمتابعة.':''}</p><div class="setup-footer"><span class="inline-note">${icon('lock')}الملفات المختارة فقط. دون تعديل أو تشغيل.</span><div class="main-action-group"><button class="primary" id="scope-button" data-action="scope" ${!ready()?'disabled':''}>فحص النطاق</button><span class="shortcut-hint"><kbd dir="ltr">Ctrl / ⌘ + Enter</kbd></span></div></div></section><aside class="start-preview" aria-label="مثال على التقرير"><div class="preview-head"><h2>من المتطلب إلى الدليل</h2><span>مثال تفاعلي</span></div>${interactivePreview()}<div class="principles"><div class="principle"><span class="principle-icon">${icon('target')}</span><div><h3>نطاق تختاره أنت</h3><p>تبدأ المراجعة من الملفات والمتطلبات التي تحددها.</p></div></div><div class="principle"><span class="principle-icon">${icon('list')}</span><div><h3>حالة مفهومة لكل متطلب</h3><p>ما يبدو مستوفًى، وما يحتاج مراجعة، وما تعذّر التحقق منه.</p></div></div><div class="principle"><span class="principle-icon">${icon('code')}</span><div><h3>ملاحظة لها سياق</h3><p>ارجع إلى الملف والسطر، وافهم سبب الملاحظة.</p></div></div></div><p class="prototype-note"><strong>جاهز للتجربة:</strong> المثال الحالي يحتوي ${n(3)} ملفات و${n(6)} متطلبات. النتائج توضيحية ولا تمثل فحصًا فعليًا.</p></aside></div>`;}
  function scope(){const stages=['تجهيز المعاينة','عرض المتطلبات','فتح التقرير التوضيحي'];return `<div class="intro"><div><span class="eyebrow">${icon('lock')}النطاق واضح قبل المراجعة.</span><h1 id="page-heading" tabindex="-1">فحص النطاق</h1><p>${esc(state.name||'مراجعة '+date.format(new Date()))}</p></div><span class="pill read-only">${icon('lock')}قراءة فقط</span></div><div class="scope-layout"><section class="panel manifest"><div class="panel-heading"><h2>الملفات ضمن هذه المراجعة</h2><span class="caption">${n(state.files.length)} ملفات</span></div><div class="panel-body"><ul class="file-list">${fileItems(false)}</ul><div class="scope-meta"><span><strong>${n(state.files.length)}</strong> ملفات مختارة</span><span><strong>${n(reqLines().length)}</strong> متطلبات</span></div><h3>المتطلبات التي أدخلتها</h3><ol class="scope-requirements">${reqLines().map((r,i)=>`<li><span class="req-number">${n(i+1)}</span><span>${esc(r)}</span></li>`).join('')}</ol></div></section><section class="panel run-pane" aria-label="حالة المراجعة"><span class="run-symbol">${icon(state.busy?'clock':'code')}</span><div><h2 id="run-heading">${state.busy?'تحضير التقرير التوضيحي':'جاهز للمراجعة'}</h2><p>لن تُعدّل الملفات، ولن يُشغّل الكود أو الاختبارات.</p></div>${state.busy?`<ol class="running-steps">${stages.map((s,i)=>`<li class="${i===state.runStage?'active':i<state.runStage?'complete':''}"><span>${i<state.runStage?icon('check'):n(i+1)}</span><span>${s}</span></li>`).join('')}</ol>`:`<div class="notice">${icon('info')}<div><strong>أنت تستعرض نموذج التصميم</strong><p>التقرير التالي يستخدم بيانات مثال تسجيل الدخول الجاهز.</p></div></div>${blockedNotice()}<div class="scope-buttons"><button class="primary" data-action="run">بدء المراجعة</button><button class="link-button" data-action="edit">تعديل الاختيار</button></div>`}</section></div>`;}
  function summary(){return `<div class="summary-strip" aria-label="ملخص التقرير">${['appears_met','needs_review','unverifiable'].map(s=>`<div class="summary-item ${statusClass(s)}">${icon(statusIcon(s))}<strong>${n(sample.review.results.filter(r=>r.status===s).length)}</strong><span class="summary-label">${labels[s]}</span></div>`).join('')}<span class="summary-scope">${n(3)} ملفات، ${n(6)} متطلبات، قراءة فقط</span></div>`;}
  function filtered(){let rows=sample.review.results.slice();if(state.file)rows=rows.filter(r=>r.evidence?.file===state.file);if(state.filter==='attention')rows=rows.filter(r=>r.status!=='appears_met').sort((a,b)=>(a.status==='needs_review'?0:1)-(b.status==='needs_review'?0:1));else if(state.filter!=='all')rows=rows.filter(r=>r.status===state.filter);return rows;}
  function evidence(){const r=sample.review.results.find(r=>r.id===state.selected);if(!r)return `<section class="panel evidence-pane" id="evidence-panel" role="tabpanel" aria-label="الدليل"><div class="evidence-header"><h2>لا توجد ملاحظة مختارة</h2><p>اختر متطلبًا من نتائج التصفية، أو اعرض كل الملفات.</p><button class="link-button mobile-back" data-action="tab" data-value="requirements">رجوع للمتطلبات</button></div></section>`;return `<section class="panel evidence-pane" id="evidence-panel" role="tabpanel" aria-label="الدليل للمتطلب المختار"><div class="evidence-header">${statusPill(r.status)}<h2>${esc(r.requirement)}</h2><p>الدليل مرتبط بهذا المتطلب ضمن الملفات المختارة.</p><button class="link-button mobile-back" data-action="tab" data-value="requirements">رجوع للمتطلبات</button></div><div class="evidence-content">${r.evidence?`${codeWindow(r.evidence,true)}<div class="analysis-block"><h3>${icon('info')}لماذا ظهرت هذه النتيجة؟</h3><p>${esc(r.explanation)}</p></div>${r.manualNextStep?`<div class="analysis-block"><h3>${icon('target')}ما الذي تراجعه يدويًا؟</h3><p>${esc(r.manualNextStep)}</p></div>`:''}`:`<div class="unverifiable-block">${icon('unknown')}<h3>لا توجد أدلة كافية ضمن هذا النطاق</h3><p>${esc(r.explanation)}</p></div><div class="analysis-block"><h3>${icon('target')}ما الذي يلزم للتحقق؟</h3><p>${esc(r.manualNextStep)}</p></div>`}</div></section>`;}
  function report(){const rows=filtered();return `<div class="intro report-intro"><div><span class="eyebrow">${icon('code')}بيانات توضيحية</span><h1 id="page-heading" tabindex="-1">تقرير النتائج</h1><p>${esc(state.name||sample.review.name)}، ${date.format(new Date())}</p></div><div class="report-actions"><button class="secondary desktop-only" id="focus-view-button" data-action="focus-view" aria-pressed="${state.focus}">${icon('focus')}${state.focus?'إظهار المتطلبات':'وضع التركيز'}</button><button class="secondary" data-action="edit">تعديل المراجعة</button></div></div>${summary()}<div class="report-tabs" role="tablist" aria-label="عرض التقرير"><button class="report-tab" id="requirements-tab" role="tab" aria-controls="requirements-panel" aria-selected="${state.tab==='requirements'}" tabindex="${state.tab==='requirements'?0:-1}" data-action="tab" data-value="requirements">المتطلبات</button><button class="report-tab" id="evidence-tab" role="tab" aria-controls="evidence-panel" aria-selected="${state.tab==='evidence'}" tabindex="${state.tab==='evidence'?0:-1}" data-action="tab" data-value="evidence">الدليل</button></div><div class="report-layout ${state.focus?'focused':''}" data-tab="${state.tab}"><aside class="panel file-nav" aria-label="ملفات المراجعة"><h2>الملفات المختارة</h2><button class="file-nav-button ${!state.file?'active':''}" data-action="file-filter" data-value="all">${icon('files')}كل الملفات</button>${sample.review.selectedFiles.map(f=>`<button class="file-nav-button ${state.file===f?'active':''}" data-action="file-filter" data-value="${esc(f)}">${icon('file')}<bdi dir="ltr">${esc(f)}</bdi></button>`).join('')}<span class="inline-note">${icon('lock')}نطاق للقراءة فقط</span></aside><section class="panel requirements-pane" id="requirements-panel" role="tabpanel" aria-label="المتطلبات ونتائجها"><div class="requirements-head"><h2>المتطلبات <span class="caption">${n(rows.length)} من ${n(6)}</span></h2><div class="filters" role="group" aria-label="تصفية المتطلبات">${[['all','الكل'],['attention','يحتاج انتباهك'],['appears_met','يبدو مستوفًى']].map(([v,t])=>`<button class="filter-button ${state.filter===v?'active':''}" data-action="filter" data-value="${v}" aria-pressed="${state.filter===v}">${t}</button>`).join('')}</div></div>${rows.length?`<ul class="requirement-list">${rows.map(r=>`<li><button class="requirement-button ${state.selected===r.id?'selected':''} ${r.status}" data-action="select" data-value="${r.id}" aria-pressed="${state.selected===r.id}"><span class="req-top"><span>${esc(r.requirement)}</span><span class="req-id">${n(r.order)}</span></span><span class="req-status ${statusClass(r.status)}">${icon(statusIcon(r.status))}${labels[r.status]}</span></button></li>`).join('')}</ul>`:'<p class="empty-list">لا توجد نتائج مرتبطة بهذا الملف ضمن التصفية الحالية.</p>'}${state.filter==='attention'?'<div class="all-results-action"><button class="link-button" data-action="filter" data-value="all">عرض جميع المتطلبات الستة</button></div>':''}</section>${evidence()}</div><section class="limits" aria-label="حدود الفحص"><strong>${icon('info')}حدود الفحص</strong><p>${icon('lock')}لم يُشغّل الكود أو الاختبارات.</p><p>لا يضمن الفحص خلو الكود من الأخطاء.</p></section>`;}
  function render(motion={}){app.innerHTML=header()+`<main class="shell ${motion.view?'view-enter':''}" id="main">${state.step===0?setup():state.step===1?scope():report()}</main>`+footer()+shortcutsDialog();if(motion.evidence)document.getElementById('evidence-panel')?.classList.add('evidence-enter');if(motion.preview)document.getElementById('interactive-preview')?.classList.add('evidence-enter');bindDrop();}
  function interactivePreview(){const r=sample.review.results.find(r=>r.id===state.preview)||sample.review.results[3];return `<section class="preview-showcase" id="interactive-preview" aria-label="تجربة أدلة المثال"><div class="preview-tabs" role="group" aria-label="اختيار مثال الدليل">${[['r4','البريد'],['r5','رسالة الخطأ'],['r6','حدود الفحص']].map(([id,label])=>`<button class="preview-tab ${state.preview===id?'active':''}" data-action="preview-evidence" data-value="${id}" aria-pressed="${state.preview===id}">${label}</button>`).join('')}</div><div class="preview-block">${statusPill(r.status)}<h3 class="preview-note-title">${esc(r.requirement)}</h3>${r.evidence?codeWindow(r.evidence,true):`<div class="preview-unknown">${icon('unknown')}<strong>الخادم خارج الملفات المختارة</strong><span>لذلك لا يمكن تأكيد سلوك تسجيل الدخول.</span></div>`}<p class="explanation">${esc(r.explanation)}</p></div></section>`;}
  function shortcutsDialog(){return `<dialog id="shortcuts-dialog" aria-labelledby="shortcuts-heading"><div class="dialog-head"><h2 id="shortcuts-heading">اختصارات تختصر الطريق</h2><button class="icon-button" data-action="close-shortcuts" aria-label="إغلاق الاختصارات">${icon('close')}</button></div><dl class="shortcut-list"><div><dt><kbd dir="ltr">Ctrl / ⌘ + Enter</kbd></dt><dd>المتابعة من المدخلات إلى النطاق، ثم بدء المثال.</dd></div><div><dt><kbd dir="ltr">J</kbd><kbd dir="ltr">K</kbd></dt><dd>الملاحظة التالية أو السابقة ضمن نتائج التصفية.</dd></div><div><dt><kbd dir="ltr">F</kbd></dt><dd>وضع التركيز على اللابتوب، أو تبديل الدليل على الجوال.</dd></div><div><dt><kbd dir="ltr">Esc</kbd></dt><dd>الخروج من التركيز، أو الرجوع للمتطلبات على الجوال.</dd></div><div><dt><kbd dir="ltr">?</kbd></dt><dd>فتح هذه الاختصارات.</dd></div></dl><p>الحروف المفردة لا تعمل أثناء الكتابة داخل الحقول.</p><button class="primary" data-action="close-shortcuts">فهمت</button></dialog>`;}
  function selectRequirement(id){const r=sample.review.results.find(r=>r.id===id);if(!r)return;state.selected=id;const mobile=window.matchMedia('(max-width: 767px)').matches;if(mobile)state.tab='evidence';render({evidence:true});announce(r.requirement+'، '+labels[r.status]);if(mobile)document.getElementById('evidence-tab')?.focus();else if(state.focus)document.getElementById('focus-view-button')?.focus();else document.querySelector(`[data-action="select"][data-value="${id}"]`)?.focus();}
  function toggleFocus(){if(state.step!==2)return;if(window.matchMedia('(max-width: 767px)').matches){state.tab=state.tab==='evidence'?'requirements':'evidence';render({evidence:true});document.getElementById(state.tab==='evidence'?'evidence-tab':'requirements-tab')?.focus();}else{state.focus=!state.focus;render({evidence:true});document.getElementById('focus-view-button')?.focus();}announce(state.focus?'وضع التركيز. اضغط Escape لإظهار المتطلبات.':'يمكنك متابعة مراجعة المتطلبات.');}
  function bindDrop(){const zone=document.getElementById('drop-zone');if(!zone)return;zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging')});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();setFiles([...e.dataTransfer.files])});}
  function setFiles(files){if(!files.length)return;state.files=files.map(f=>({name:f.name,demo:false}));state.reached=0;state.customBlocked=false;render();announce('تم اختيار '+n(files.length)+' ملفات. تُعرض الأسماء فقط في المعاينة.');document.querySelector('[data-action="pick-files"]')?.focus();}
  function invalidate(){state.reached=0;state.customBlocked=false;}
  function resetExample(){if(state.busy)return;state.name=sample.review.name;state.requirements=sample.review.inputRequirements.join('\n');state.files=sample.review.selectedFiles.map(name=>({name,demo:true}));state.reached=0;state.selected='r4';state.filter='attention';state.file=null;state.tab='requirements';state.customBlocked=false;stage(0);announce('تمت استعادة مثال تسجيل الدخول الجاهز.');}
  const pause=ms=>new Promise(resolve=>setTimeout(resolve,ms));
  async function run(){if(state.busy)return;if(!demo()){state.customBlocked=true;render();document.getElementById('custom-notice')?.scrollIntoView({block:'nearest'});announce('التحليل الفعلي غير مفعّل. استعد المثال الجاهز لتجربة التقرير.');return;}state.busy=true;state.runStage=0;for(let i=0;i<3;i++){state.runStage=i;render();announce(['تجهيز المعاينة','عرض المتطلبات','فتح التقرير التوضيحي'][i]);await pause(420);}state.busy=false;state.selected='r4';state.file=null;state.tab='requirements';state.filter=window.matchMedia('(max-width: 767px)').matches?'attention':'all';stage(2);}
  app.addEventListener('input',e=>{if(e.target.id==='review-name')state.name=e.target.value;if(e.target.id==='requirements'){state.requirements=e.target.value;invalidate();document.getElementById('requirements-count').textContent=n(reqLines().length)+' متطلبات';const button=document.getElementById('scope-button');if(button)button.disabled=!ready();document.getElementById('validation').textContent=ready()?'':'اختر ملفًا واحدًا على الأقل وأضف المتطلبات للمتابعة.';}});
  app.addEventListener('change',e=>{if(e.target.id==='file-input')setFiles([...e.target.files]);});
  app.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action,value=el.dataset.value;
    if(action==='pick-files')document.getElementById('file-input').click();
    else if(action==='remove-file'){state.files.splice(Number(value),1);invalidate();render();announce('تمت إزالة الملف.');document.querySelector('[data-action="pick-files"]')?.focus();}
    else if(action==='scope'&&ready())stage(1);
    else if(action==='home'||action==='edit')stage(0);
    else if(action==='stage'&&Number(value)<=state.reached)stage(Number(value));
    else if(action==='example')resetExample();
    else if(action==='run')run();
    else if(action==='filter'){state.filter=value;const rows=filtered();if(!rows.some(r=>r.id===state.selected))state.selected=rows[0]?.id||null;render();document.querySelector(`[data-action="filter"][data-value="${value}"]`)?.focus();announce('عدد المتطلبات الظاهرة '+n(rows.length));}
    else if(action==='file-filter'){state.file=value==='all'?null:value;const rows=filtered();state.selected=rows[0]?.id||null;render();document.querySelector(`[data-action="file-filter"][data-value="${value}"]`)?.focus();announce(rows.length?'تم عرض المتطلبات المرتبطة بالملف.':'لا توجد نتائج مرتبطة بهذا الملف ضمن التصفية الحالية.');}
    else if(action==='select')selectRequirement(value);
    else if(action==='tab'){state.tab=value;render();document.getElementById(value==='evidence'?'evidence-tab':'requirements-tab')?.focus();}
    else if(action==='preview-evidence'){state.preview=value;render({preview:true});document.querySelector(`[data-action="preview-evidence"][data-value="${value}"]`)?.focus();announce(sample.review.results.find(r=>r.id===value).requirement);}
    else if(action==='focus-view')toggleFocus();
    else if(action==='shortcuts')document.getElementById('shortcuts-dialog').showModal();
    else if(action==='close-shortcuts')document.getElementById('shortcuts-dialog').close();
    else if(action==='about')document.getElementById('about-dialog').showModal();
    else if(action==='close-dialog')document.getElementById('about-dialog').close();
  });
  app.addEventListener('keydown',e=>{
    if(document.getElementById('about-dialog')?.open||document.getElementById('shortcuts-dialog')?.open)return;
    const typing=e.target.matches?.('input,textarea,select,[contenteditable="true"]');
    if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){
      e.preventDefault();if(state.busy)return;
      if(state.step===0&&ready())stage(1);else if(state.step===1)run();return;
    }
    if(e.target.getAttribute?.('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){
      e.preventDefault();state.tab=e.key==='Home'?'requirements':e.key==='End'?'evidence':state.tab==='requirements'?'evidence':'requirements';render();document.getElementById(state.tab==='requirements'?'requirements-tab':'evidence-tab').focus();return;
    }
    if(typing||e.ctrlKey||e.metaKey||e.altKey||state.busy)return;
    if(e.key==='?'){e.preventDefault();document.getElementById('shortcuts-dialog').showModal();return;}
    if(state.step!==2)return;
    if(['j','k','J','K'].includes(e.key)){
      e.preventDefault();const rows=filtered();if(!rows.length)return;let at=rows.findIndex(r=>r.id===state.selected);if(at<0)at=0;const delta=e.key.toLowerCase()==='j'?1:-1;selectRequirement(rows[(at+delta+rows.length)%rows.length].id);
    }else if(e.key.toLowerCase()==='f'){e.preventDefault();toggleFocus();}
    else if(e.key==='Escape'){
      if(state.focus){e.preventDefault();toggleFocus();}
      else if(window.matchMedia('(max-width: 767px)').matches&&state.tab==='evidence'){state.tab='requirements';render();document.getElementById('requirements-tab')?.focus();}
    }
  });
  render();
})();
